 function playDefaultSound(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=audioContextRef.current||(audioContextRef.current=new AC());if(ctx.state==='suspended')ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(740,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(520,ctx.currentTime+0.11);gain.gain.setValueAtTime(0.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(0.12,ctx.currentTime+0.015);gain.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+0.19);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+0.2);}catch{}}
 async function askVyroAI(textValue){const isImage=textValue.startsWith('لطفاً برای این درخواست تصویر بساز:');const prompt=textValue.replace('لطفاً برای این درخواست تصویر بساز:','').trim();const messages=[...aiMessages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.text})),{role:'user',content:textValue}];setAiMessages(prev=>[...prev,{role:'user',text:textValue}]);setAiLoading(true);try{if(!supabaseReady)throw new Error('service unavailable');const {data,error}=await supabase.functions.invoke('vyro-ai',{body:isImage?{imagePrompt:prompt}:{messages}});if(error)throw error;if(isImage){if(!data?.imageUrl)throw new Error('image unavailable');setAiMessages(prev=>[...prev,{role:'assistant',text:'تصویر آماده شد ✨',imageUrl:data.imageUrl}]);}else{const answer=data?.answer||data?.choices?.[0]?.message?.content;if(!answer)throw new Error('empty response');setAiMessages(prev=>[...prev,{role:'assistant',text:answer}]);}}catch(err){setAiMessages(prev=>[...prev,{role:'assistant',text:isImage?'ساخت تصویر فعلاً در دسترس نیست. بررسی کن کلید OpenAI و دسترسی مدل تصویر در سرور تنظیم باشند.':'فعلاً نتونستم وصل بشم. لطفاً کمی بعد دوباره تلاش کن.'}]);}finally{setAiLoading(false);}}
 async function searchSpotify(){const q=musicName.trim();if(!q){setNotice('نام آهنگ، هنرمند یا آلبوم را بنویس.');return;}setSpotifyLoading(true);setSpotifySearched(true);try{if(!supabaseReady)throw new Error('اتصال Supabase تنظیم نشده است.');const {data,error}=await supabase.functions.invoke('spotify-search',{body:{query:q}});if(error)throw error;setSpotifyResults(data?.tracks||[]);if(!data?.tracks?.length)setNotice('نتیجه‌ای پیدا نشد.');}catch(err){setSpotifyResults([]);setNotice('فعلاً جست‌وجوی موسیقی در دسترس نیست. لطفاً بعداً دوباره امتحان کن.');}finally{setSpotifyLoading(false);}}
 async function uploadProfileAsset(e,kind){const file=e.target.files?.[0];if(!file)return;const local=URL.createObjectURL(file);if(kind==='avatar')setProfileAvatar(local);else setProfileBanner(local);if(!supabaseReady||!session){setNotice('تصویر انتخاب شد؛ برای ذخیره بین دستگاه‌ها باید وارد حساب شوی.');return}try{const ext=(file.name.split('.').pop()||'jpg').replace(/[^a-zA-Z0-9]/g,'');const path=`${session.user.id}/${kind}-${Date.now()}.${ext}`;const {error}=await supabase.storage.from('avatars').upload(path,file,{upsert:true});if(error)throw error;const {data}=supabase.storage.from('avatars').getPublicUrl(path);const url=data.publicUrl;if(kind==='avatar')setProfileAvatar(url);else setProfileBanner(url);let metadata;if(kind==='avatar'){const next=[...profileAvatarHistory.filter(x=>x!==url),url].slice(-2);setProfileAvatarHistory(next);metadata={avatar_url:url,avatar_history:next}}else metadata={banner_url:url};const {error:profileError}=await supabase.from('profiles').update(kind==='avatar'?{avatar_url:url}:{banner_url:url}).eq('id',session.user.id);if(profileError)throw profileError;const {error:metaError}=await supabase.auth.updateUser({data:metadata});if(metaError)throw metaError;setNotice('تصویر پروفایل ذخیره شد.')}catch(err){setNotice('تصویر فعلاً فقط در همین دستگاه نمایش داده می‌شود؛ دسترسی ذخیره‌سازی آواتار باید فعال شود.')}}
 async function saveDownload(url,filename='download'){try{const response=await fetch(url);if(!response.ok)throw new Error('download failed');const blob=await response.blob();const reader=new FileReader();reader.onloadend=async()=>{try{const base64=String(reader.result).split(',')[1];await Filesystem.writeFile({path:'VYRO/Downloads/'+filename.replace(/[^a-zA-Z0-9._-]/g,'_'),data:base64,directory:Directory.Documents,recursive:true});setNotice('فایل در پوشهٔ VYRO/Downloads در فضای اسناد برنامه ذخیره شد.');}catch{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);setNotice('دانلود در دستگاه شروع شد.');}};reader.readAsDataURL(blob);}catch{window.open(url,'_blank','noopener,noreferrer');setNotice('این منبع دانلود مستقیم را نمی‌پذیرد؛ در مرورگر باز شد.');}}
