 {settingsPage==='deleteAccount'&&<><h2>تأیید حذف حساب</h2><p>برای امنیت، نام کاربری و رمز عبور را وارد کن؛ رمز عبور باید دوبار یکسان وارد شود.</p><form className="settings-detail" onSubmit={deleteMyAccount}><label>نام کاربری<input value={deleteUsername} onChange={e=>setDeleteUsername(e.target.value)} autoCapitalize="none" placeholder="mohammad0900" required/></label><label>رمز عبور<input type="password" value={deletePassword} onChange={e=>setDeletePassword(e.target.value)} autoComplete="current-password" required/></label><label>تکرار رمز عبور<input type="password" value={deletePasswordAgain} onChange={e=>setDeletePasswordAgain(e.target.value)} autoComplete="current-password" required/></label><button className="danger-btn" type="submit" disabled={busy}>{busy?'در حال حذف…':'تأیید نهایی و حذف حساب'}</button></form></>}
