   {tab==='profile'&&<section className="profile-page card"><div className="profile-top-actions"><span></span><button className="icon-btn" aria-label="تنظیمات پروفایل" onClick={()=>{setSettingsPage('home');setTab('settings')}}><Settings size={19}/></button></div><div className="profile-cover" style={profileBanner?{backgroundImage:`url(${profileBanner})`,backgroundSize:"cover",backgroundPosition:"center"}:{}}><label className="banner-edit" title="انتخاب بنر"><ImagePlus size={16}/><input type="file" accept="image/*" onChange={e=>uploadProfileAsset(e,"banner")}/></label></div><div className="profile-main"><label className="avatar large profile-avatar-control">{profileAvatar?<img src={profileAvatar} alt="عکس پروفایل"/>:(session.user?.user_metadata?.username||"V")[0]?.toUpperCase()||"V"}<span className="avatar-plus"><Plus size={14}/></span><input type="file" accept="image/*" onChange={e=>uploadProfileAsset(e,"avatar")}/></label>{profileAvatarHistory.length>0&&<div className="avatar-history">{profileAvatarHistory.map((url,i)=><button type="button" key={url} className={profileAvatar===url?'selected':''} onClick={async()=>{setProfileAvatar(url);try{await supabase.auth.updateUser({data:{avatar_url:url}});await supabase.from('profiles').update({avatar_url:url}).eq('id',session.user.id)}catch{}}} title={'عکس پروفایل '+(i+1)}><img src={url} alt={'عکس پروفایل '+(i+1)}/></button>)}</div>}<div className="profile-identity"><h2>@{session.user?.user_metadata?.username||'vyro_user'}</h2><p>@{session.user?.user_metadata?.username||session.user.email?.split('@')[0]}</p>{editingBio?<form onSubmit={async e=>{e.preventDefault();setEditingBio(false);const {error}=await supabase.auth.updateUser({data:{bio:profileBio}});const {error:profileError}=await supabase.from('profiles').update({bio:profileBio}).eq('id',session.user.id);if(error||profileError)setNotice('ذخیره بیو انجام نشد.')}}><input value={profileBio} onChange={e=>setProfileBio(e.target.value)} maxLength={160}/><button className="text-link" type="submit">ذخیره</button></form>:<small onClick={()=>setEditingBio(true)}>{profileBio||'به دنیای وایرو خوش اومدی ✨'} <button type="button" className="bio-edit" onClick={e=>{e.stopPropagation();setEditingBio(true)}}>✎</button></small>}</div><button className="secondary-btn" onClick={()=>setEditingBio(true)}>ویرایش بیو</button></div><div className="profile-stats"><div><b>{posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length}</b><span>پست</span></div><div><b>۰</b><span>دنبال‌کننده</span></div><div><b>۰</b><span>دنبال‌شونده</span></div></div>{posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length>0?<div className="profile-shortcuts profile-tabs"><button className={profileSection==='music'?'selected':''} onClick={()=>setProfileSection('music')}>موزیو</button><button className={profileSection==='vyriou'?'selected':''} onClick={()=>setProfileSection('vyriou')}>ویریو</button><button className={profileSection==='variou'?'selected':''} onClick={()=>setProfileSection('variou')}>واریو</button><button className={profileSection==='review'?'selected':''} onClick={()=>setProfileSection('review')}>ریویو</button></div>:<div className="empty-state">هنوز پستی منتشر نشده.</div>}{profileSection==='variou'&&posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length>0&&<div className="profile-posts"><h3>واریو · نوشته‌ها</h3>{posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length?posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).map(p=><article key={p.id} className="profile-post"><p>{p.content}</p>{p.media_url&&<a href={p.media_url} target="_blank" rel="noreferrer">نمایش رسانه</a>}</article>):<div className="empty-state">هنوز پستی منتشر نشده.</div>}</div>}{profileSection==='vyriou'&&posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length>0&&<div className="profile-posts"><h3>ویریو · عکس‌ها و ویدیوها</h3>{posts.filter(p=>p.media_url).map(p=><article key={p.id} className="profile-post">{p.media_type?.startsWith('video/')?<video controls src={p.media_url}/>:<img src={p.media_url} alt="رسانه"/>}</article>)}<div className="empty-state">رسانه‌های حساب پس از اتصال ذخیره‌سازی آنلاین در اینجا جمع می‌شوند.</div></div>}{profileSection==='music'&&posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length>0&&<div className="profile-posts"><h3>موسیقی‌های من</h3><button className="secondary-btn" onClick={()=>setTab('music')}>رفتن به موزیو و انتخاب موسیقی</button></div>}{profileSection==='review'&&posts.filter(p=>p.username===(session.user?.user_metadata?.username||session.user.email?.split('@')[0])).length>0&&<div className="profile-posts"><h3>ریویو · بازنشرها</h3><div className="empty-state">هنوز بازنشری انجام ندادی.</div></div>}<div className="profile-legal-note">قوانین و مقررات وایرو</div></section>}
   {tab==='support'&&<section className="admin-panel card"><div className="admin-head"><button className="settings-back admin-back" onClick={()=>{setTab("profile");setChatId(null)}}><ChevronLeft size={18}/> بازگشت</button><div><span className="feature-icon"><ShieldCheck size={24}/></span><h2>مدیریت وایرو</h2><p>فهرست زیر نمایشی است؛ محدودسازی و حذف واقعی باید به API امن سرور متصل شود.</p></div><button className="admin-users-button" onClick={()=>setAdminView(adminView==='home'?'banned':'home')} aria-label="فهرست کاربران"><UserRound size={20}/></button></div>{adminView==='home'?<><div className="admin-search"><Search size={17}/><input value={adminSearch} onChange={e=>setAdminSearch(e.target.value)} placeholder="جست‌وجوی نام یا نام کاربری…"/></div><div className="admin-list">{adminUsers.filter(u=>u.status==='active'&&(u.name+' '+u.username).toLowerCase().includes(adminSearch.toLowerCase())).map(u=><div className="admin-user-row" key={u.id}><span className="admin-avatar">{u.name.slice(0,1)}</span><div className="admin-user-info"><b>{u.name}</b><small>@{u.username}</small></div><div className="track-menu-wrap"><button className="track-icon" onClick={()=>setAdminMenu(adminMenu===u.id?null:u.id)}>•••</button>{adminMenu===u.id&&<div className="track-menu"><button onClick={()=>{setAdminUsers(v=>v.map(x=>x.id===u.id?{...x,status:'banned'}:x));setAdminMenu(null)}}>محدود / تعلیق</button><button onClick={()=>{setAdminUsers(v=>v.map(x=>x.id===u.id?{...x,status:'deleted'}:x));setAdminMenu(null)}}>انتقال به حذف‌شده‌ها</button></div>}</div></div>)}</div><button className="secondary-btn" onClick={()=>setAdminView('banned')}>بن‌شده‌ها / حذف‌شده‌ها</button></>:<><div className="admin-subtabs"><button onClick={()=>setAdminView('banned')}>بن‌شده‌ها</button><button onClick={()=>setAdminView('deleted')}>حذف‌شده‌ها</button><button onClick={()=>setAdminView('home')}>بازگشت</button></div><div className="admin-search"><Search size={17}/><input value={adminSearch} onChange={e=>setAdminSearch(e.target.value)} placeholder="جست‌وجوی این فهرست…"/></div><div className="admin-list">{adminUsers.filter(u=>u.status===(adminView==='deleted'?'deleted':'banned')&&(u.name+' '+u.username).toLowerCase().includes(adminSearch.toLowerCase())).map(u=><div className="admin-user-row" key={u.id}><span className="admin-avatar">{u.name.slice(0,1)}</span><div className="admin-user-info"><b>{u.name}</b><small>@{u.username}</small></div>{adminView==='banned'?<button className="secondary-btn" onClick={()=>setAdminUsers(v=>v.map(x=>x.id===u.id?{...x,status:'active'}:x))}>رفع تعلیق</button>:<button className="danger-icon" onClick={()=>setAdminUsers(v=>v.filter(x=>x.id!==u.id))} aria-label="حذف دائم">▣</button>}</div>)}</div>{adminView==='deleted'&&<button className="danger-btn" onClick={()=>setAdminUsers(v=>v.filter(x=>x.status!=='deleted'))}>حذف همهٔ حساب‌های حذف‌شده</button>}</>}</section>}
